+import assert from 'node:assert/strict';
+import { after, before, describe, it } from 'node:test';
+import { api, startTestServer, type TestServer } from './helpers.ts';
+
+const CARRIERS = ['ATP', 'DHL', 'DPD', 'GLS', 'UPS'] as const;
+const SHIPMENTS = 5000;
+
+describe('GET /shipments on a staging-sized dataset (5k shipments)', () => {
+  let srv: TestServer;
+  let firstId: string;
+
+  before(async () => {
+    srv = await startTestServer();
+    const base = Date.parse('2026-06-01T08:00:00Z');
+    for (let i = 0; i < SHIPMENTS; i++) {
+      const s = srv.store.addShipment(
+        {
+          trackingNumber: `PERF${i}`,
+          carrier: CARRIERS[i % CARRIERS.length],
+          serviceLevel: 'standard',
+          recipient: { name: 'Anna Huber', street: 'Mariahilfer Straße 1', zip: '1060', city: 'Wien', country: 'AT' },
+        },
+        new Date(base + i * 60_000),
+      );
+      if (i === SHIPMENTS - 1) firstId = s.id; // newest = first in the list
+      if (i % 2) srv.store.addEvent(s.id, 'picked_up', { at: new Date(base + i * 60_000 + 3_600_000).toISOString() });
+    }
+  });
+
+  after(async () => {
+    await srv.close();
+  });
+
+  it('only returns (and computes eta for) one page, not all shipments', async () => {
+    const res = await api(srv.url, 'GET', '/shipments');
+    assert.equal(res.status, 200);
+    assert.equal(res.body.count, 50);
+    assert.equal(res.body.items.length, 50);
+    for (const item of res.body.items) assert.match(item.eta, /^\d{4}-\d{2}-\d{2}$/);
+
+    const big = await api(srv.url, 'GET', '/shipments?limit=100000');
+    assert.equal(big.body.count, 500, 'limit is capped at 500');
+  });
+
+  it('answers well within a generous time bound (regression guard, not a benchmark)', async () => {
+    await api(srv.url, 'GET', '/shipments'); // warm up
+    const t = performance.now();
+    for (let i = 0; i < 10; i++) await api(srv.url, 'GET', '/shipments?limit=500');
+    const avgMs = (performance.now() - t) / 10;
+    assert.ok(avgMs < 200, `list of 500 took ${avgMs.toFixed(1)} ms on average`);
+  });
+
+  it('still shows a fresh eta after a new event (no caching)', async () => {
+    const before = (await api(srv.url, 'GET', '/shipments?limit=1')).body.items[0];
+    assert.equal(before.id, firstId);
+    srv.store.addEvent(firstId, 'exception', { at: '2026-06-05T10:00:00Z' });
+    const after = (await api(srv.url, 'GET', '/shipments?limit=1')).body.items[0];
+    assert.notEqual(after.eta, before.eta);
+  });
+});
